288	func deriveCheckpointURLFromInfo(info *Info, config *settings.CheckpointRemoteConfig) (string, error) {
289		switch info.Protocol {
290		case ProtocolSSH:
291			// SCP-style (git@host:repo) doesn't support ports. When a non-default
292			// port is set (e.g., from ssh://git@host:2222/...), use the ssh:// URL form.
293			if info.Port != "" {
294				return fmt.Sprintf("ssh://git@%s/%s.git", info.HostPort(), config.Repo), nil
295			}
296			return fmt.Sprintf("git@%s:%s.git", info.Host, config.Repo), nil
297		case ProtocolHTTPS:
298			return fmt.Sprintf("https://%s/%s.git", info.HostPort(), config.Repo), nil
299		default:
300			return "", fmt.Errorf("unsupported protocol %q in origin remote", info.Protocol)
301		}
302	}
303	
304	// resolveProviderCheckpointURL builds the checkpoint URL for the configured
305	// provider, choosing the transport from what's already configured for that
306	// endpoint. It is the fallback used when the push/origin remote's protocol can't
307	// be mapped to a git transport (e.g. entire://, file://): the configured
308	// checkpoint_remote names a concrete provider, so checkpoints go there rather
309	// than being misrouted to the origin remote.
310	//
311	// Transport precedence:
312	//  1. ENTIRE_CHECKPOINT_TOKEN set -> HTTPS on the provider host (the token is
313	//     the credential).
314	//  2. An existing remote already targets the provider host -> reuse its scheme,
315	//     so checkpoints use the same auth the user already has for that endpoint.
316	//  3. Otherwise SSH on the provider host.
317	//
318	// Returns ok=false when no transport can be determined (unknown provider with no
319	// usable signal), in which case the caller falls back to the origin remote.
320	func resolveProviderCheckpointURL(config *settings.CheckpointRemoteConfig, dir string) (string, bool) {
321		repo, err := openRepoAt(dir)
322		if err != nil {
323			repo = nil // Fall back to env/provider-only signals.
324		}
325	
326		info, ok := pickProviderTransport(repo, config)
327		if !ok {
328			return "", false
329		}
330		url, err := deriveCheckpointURLFromInfo(info, config)
331		if err != nil {
332			return "", false
333		}
334		return url, true
335	}
