376	// findRemoteInfoForHost returns the parsed Info of the first configured git
377	// remote (in deterministic name order) whose host matches host and whose
378	// protocol is a usable git transport (ssh/https). entire:// and other
379	// non-transport remotes are ignored.
380	func findRemoteInfoForHost(repo *git.Repository, host string) (*Info, bool) {
381		cfg, err := repo.Config()
382		if err != nil {
383			return nil, false
384		}
385		names := make([]string, 0, len(cfg.Remotes))
386		for name := range cfg.Remotes {
387			names = append(names, name)
388		}
389		sort.Strings(names)
390		for _, name := range names {
391			for _, rawURL := range cfg.Remotes[name].URLs {
392				info, err := gitremote.ParseURL(rawURL)
393				if err != nil {
394					continue
395				}
396				if strings.EqualFold(info.Host, host) && isDerivableProtocol(info.Protocol) {
397					return info, true
398				}
399			}
400		}
401		return nil, false
402	}
