404	func deriveTokenOriginURL(originURL string) (string, bool) {
405		info, err := gitremote.ParseURL(originURL)
406		if err != nil {
407			return "", false
408		}
409		if info.Host == "" || info.Owner == "" || info.Repo == "" {
410			return "", false
411		}
412		// Keep the port only when the source was already HTTPS. SSH ports
413		// (e.g., :2222) don't map to HTTPS ports on the same host.
414		hostPort := info.Host
415		if info.Protocol == ProtocolHTTPS {
416			hostPort = info.HostPort()
417		}
418		return fmt.Sprintf("https://%s/%s/%s.git", hostPort, info.Owner, info.Repo), true
419	}
